function compatible(a,b){if(isUnified){let av=avCompatible(a,b);if(av!==undefined)return av}if(a&&b&&['video','uvc'].includes(a.signal)){if(a.dir!=='out'||b.dir!=='in')return '出力端子 → 入力端子の順で接続してください';if(a.signal!==b.signal)return 'HDMI / SDI映像をUSBへ入力するにはキャプチャーが必要です';if(a.signal==='video'){let hdmi=t=>['HDMI','HDMI_MICRO'].includes(t);if(a.type!==b.type&&!(hdmi(a.type)&&hdmi(b.type)))return 'HDMIとSDIの間には対応する変換器が必要です'}else if(a.type!==b.type)return 'USB映像の端子を確認してください';return videoEdgeError(a,b)}if(a.dir!=='out'||b.dir!=='in')return '出力端子 → 入力端子の順で接続してください';if(b.signal==='speaker'&&a.signal!=='speaker')return 'パッシブスピーカーにはパワーアンプが必要です。ライン出力からは接続できません';if(a.signal==='speaker'&&b.signal!=='speaker')return 'アンプのスピーカー出力はライン入力に接続できません';if(a.signal!==b.signal&&!b.accept?.includes(a.signal))return '信号形式が異なります。PHONO・MIC・デジタル信号を確認してください';if(b.type==='COMBO'&&['XLR','TRS','TS'].includes(a.type))return null;if(a.signal==='line'&&b.signal==='line'&&['XLR','TRS'].includes(a.type)&&['XLR','TRS'].includes(b.type))return null;if(a.type!==b.type)return '端子規格が異なります。この変換ケーブルは未対応です';if(a.type==='BINDING')return 'バインディングポストは参照用です。スピコンを使用してください';return null}
function connectionError(from,fp,to,tp){let a=getport(from,fp),b=getport(to,tp);if(!a||!b)return '端子が見つかりません';let base=compatible(a,b);if(base)return base;let src=models[node(from).model],dst=models[node(to).model];if(isUnified&&typeof audioSharedInputErrors==='function'){let conflicts=audioSharedInputErrors({...state,edges:[...state.edges,{from,fp,to,tp}]});if(conflicts.length)return conflicts[0]}if(isUnified&&src.exclusiveOutputs?.includes(fp)&&state.edges.some(e=>e.from===from&&src.exclusiveOutputs.includes(e.fp)&&e.fp!==fp))return 'USB接続中の3.5mm端子は監視用です。録音出力として同時使用できません';if(b.signal==='speaker'&&src.category!=='amp')return 'スピコンはパワーアンプのスピーカー出力から接続してください';if(dst.category==='passive'&&state.edges.some(e=>e.to===to))return 'このパッシブスピーカーは接続済みです。並列接続は現在対象外です';if(src.category==='amp'&&a.signal==='speaker'&&state.edges.some(e=>e.from===from&&getport(from,e.fp)?.signal==='speaker'&&getport(from,e.fp)?.channel===a.channel))return '同じアンプチャンネルの別出力は使用中です。1チャンネル1台で接続してください';if(dst.category==='amp'&&state.edges.some(e=>e.to===to&&getport(to,e.tp)?.channel===b.channel))return '同じアンプチャンネルの入力は使用中です';return null}
function connect(id,p){if(rewire){let edge=state.edges.find(e=>e.id===rewire.edge);if(rewire.end==='to'&&edge?.from===id&&edge.fp===p){rewire=null;render();toast('差し替えを中止しました。元の接続は保持されています');return}commitRewire(id,p);return}let existing=state.edges.find(e=>(e.from===id&&e.fp===p)||(e.to===id&&e.tp===p));if(!pending&&existing){selectedEdge=existing.id;selectedGroup=null;if(getport(id,p)?.dir==='out'){startRewire('to');toast(getport(id,p).label+' は '+node(existing.to).name+' に接続済みです。差し替える入力端子を選んでください（Escで中止）');return}render();return}let port=getport(id,p);selectedEdge=null;selectedGroup=null;if(!pending){if(port.dir!=='out'){toast('先に出力端子を選んでください');return}if(occupied(id,p)){toast('接続済みの出力はクリックして接続先を差し替えられます');return}pending={node:id,port:p};toast('接続先の入力端子を選択してください（Escで中止）');render();return}if(pending.node===id&&pending.port===p){pending=null;render();return}let a=getport(pending.node,pending.port);let err=pending.node===id?'同じ機材内の接続には対応していません':occupied(id,p)?'この入力端子は使用中です':connectionError(pending.node,pending.port,id,p);if(err){toast(err);return}remember();state.edges.push({id:'e'+Date.now(),from:pending.node,fp:pending.port,to:id,tp:p,type:cableType(a,port),length:3,...(isVideo||isUnified&&['video','uvc'].includes(a.signal)?{format:defaultVideoFormat(a,port)}:{})});pending=null;render();toast('接続しました · ケーブル 1本を追加'+(isUnified&&typeof audioInputLevelWarning==='function'&&audioInputLevelWarning(a,port,node(id).name)?' / '+audioInputLevelWarning(a,port,node(id).name):''))}
function inspect(){if(typeof presenceSelectionChanged==='function')presenceSelectionChanged();if(selectedEdge){inspectCable();return}if(selectedGroup){inspectGroup();return}let n=node(selected);if(!n){$('#details').innerHTML='<p class="sub">機材を選択すると端子と仕様を表示します。</p>';return}let m=models[n.model];$('#details').innerHTML=`<span class="badge">${m.generic?'◇ 汎用イラスト / 端子構成モデル':'● 実機写真 / 物理端子モデル'}</span><div class="inspectimage"><img src="${m.img}" alt="${m.name}"></div><div class="eyebrow">${m.maker}</div><h2>${m.name}</h2><p class="description">${m.desc}</p><button id="inspectreplace" class="replaceaction">⇄ 配線を保って別の機材へ交換</button><div class="label">機材の名前</div><input id="nodename" maxlength="60" value="${esc(n.name)}"><div class="label" style="margin-top:14px">所属ブース</div><select id="nodegroup" class="groupselect" aria-label="所属ブース"><option value="">グループなし</option>${state.groups.map(g=>`<option value="${g.id}" ${n.group===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select>${isUnified?audioInfoHTML(n):''}${m.note?`<p class="note">${esc(m.note)}</p>`:''}${n.routingNote?`<p class="selectionhint">${esc(n.routingNote)}</p>`:''}<div class="divider"></div><div class="sectionhead">入出力端子 <span>${m.ports.length} PORTS</span></div><p class="source">${m.domain==='video'?'出力→入力の順に接続。映像と埋め込み音声は1本で伝送。USB映像とUSB制御は別に扱います。':'端子を選択して接続。L / R は各1本です。<br>コンボ端子はXLR / TRS / TSを共用。'}</p><div class="inspectports">${m.ports.map(p=>`<div class="inspectport" data-inspectport="${p.id}" role="button" tabindex="0" style="cursor:pointer"><b><span style="color:${colors[p.type]||colors.XLR}">${p.dir==='out'?'↗':p.dir==='in'?'↘':'↔'}</span> ${p.label}</b><span>${p.type==='COMBO'?'XLR/TRS':p.type} · ${occupied(n.id,p.id)?'使用中':'空き'}</span></div>`).join('')}</div><div class="divider"></div><div class="source">仕様・写真の出典<br><a href="${m.source}" target="_blank" rel="noreferrer">${m.generic?'音声端子・接続仕様の参考':m.sourceLabel||m.maker+' 公式製品情報'} ↗</a>${m.rental?`<br><a href="${m.rental}" target="_blank" rel="noreferrer">レンタル取扱い・写真の参照先 ↗</a>`:''}${m.photoSource?`<br><a href="${m.photoSource}" target="_blank" rel="noreferrer">実機写真の参照元 ↗</a>`:''}<p>${m.domain==='video'?'映像・音声端子に対応。PTZ機種はLAN制御にも対応。光は接続方向の演出で、実信号を検出するものではありません。電源、内部ルーティング、HDCP、EDID、ケーブル品質は実機で確認。一般のUSB制御、IP映像、PoE、タリー、リファレンス、MADIは対象外です。':'音声のアナログ／同軸デジタルを対象にした初期版。USB制御・LINKは参照用。USB音声・USB映像は対応端子から配線できます。電源、共有入力の切替、内部ルーティング、ゲインとアンプのリミッター設定は実機で確認。スピコンは1チャンネル1台のステレオ運用を対象とします。光は接続方向の演出で、実際の音声検出ではありません。'}</p></div><button class="danger" id="delete">⌫ この機材を削除</button>`;$('#inspectreplace').onclick=()=>openReplacement(n.id);$('#nodegroup').onchange=e=>{remember();n.group=e.target.value;render()};let editedName=false;$('#nodename').oninput=e=>{if(!editedName){remember();editedName=true}n.name=e.target.value.trim()||m.name;let heading=$(`.node[data-id="${n.id}"] .nodehead strong`);if(heading)heading.textContent=n.name;save();$('#undo').disabled=!history.length};$('#delete').onclick=()=>removeEquipment(n.id);$$('[data-inspectport]').forEach(el=>{el.onclick=()=>{let p=m.ports.find(p=>p.id===el.dataset.inspectport);if(p.dir==='io'){toast(p.signal==='storage'?'USBメモリー再生専用です。PC接続・USB録音には使用できません':'この端子は参照用です。対応する実機ケーブル・設定を確認してください');return}connect(n.id,p.id)};el.onkeydown=e=>{if(e.key==='Enter')el.click()}})}
function cables(){let sums={},pieces=cableInventory(state.edges);pieces.forEach(({type,segment})=>{sums[type]??={count:0,length:0};sums[type].count++;sums[type].length+=segment.length});$('#cableview').innerHTML=`<h2>ケーブルリスト（全接続）</h2><p>延長は区間ごとに1本として集計。${state.edges.length}経路 / ${pieces.length}本。L / Rは各1本です。</p><div class="summary">${Object.entries(sums).map(([t,s])=>`<div>${t}<b>${s.count} <small>本</small></b><small>合計 ${cableLengthText(s.length)}</small></div>`).join('')}</div><button id="csv">↓ CSVを書き出す</button><table><thead><tr><th>No.</th><th>出力機材 / 端子</th><th>入力機材 / 端子</th><th>ケーブル / 区間</th><th>長さ m</th><th>コメント</th><th></th></tr></thead><tbody>${pieces.map(({edge:e,segment:s,index,type},i)=>`<tr><td>${String(i+1).padStart(2,'0')}</td><td>${esc(node(e.from).name)}<br><small>${getport(e.from,e.fp).label}</small></td><td>${esc(node(e.to).name)}<br><small>${getport(e.to,e.tp).label}</small></td><td style="color:${colors[type]||colors[e.type]}">${cableLabel(type)}${cableSegments(e).length>1?`<br><small>${index?'延長 '+index:'ケーブル 1'} / 合計 ${cableLengthText(e.length)}</small>`:''}${(isVideo||isUnified)&&videoFormats(getport(e.from,e.fp),getport(e.to,e.tp)).length?'<br><small>'+esc(e.format||'フォーマット未設定')+'</small>':''}</td><td><input type="number" min="0.1" max="1000" step="0.1" value="${s.length}" data-length="${e.id}" data-piece="${index}" aria-label="ケーブル長"></td><td>${esc(s.note||'—')}</td><td><button data-edit-edge="${e.id}">編集</button><button data-delete-edge="${e.id}">経路削除</button></td></tr>`).join('')}</tbody></table><p>中継コネクターや伝送方式は実機に合わせて用意してください。長距離の映像・USBは中継方法も確認してください。</p>`;$$('[data-delete-edge]').forEach(el=>el.onclick=()=>deleteCable(el.dataset.deleteEdge));$$('[data-edit-edge]').forEach(el=>el.onclick=()=>{selectedEdge=el.dataset.editEdge;selectedGroup=null;pending=null;rewire=null;insertDraft=null;$('[data-tab="canvas"]').click();inspect();renderRouteEditor();wires()});$$('[data-length]').forEach(el=>el.onchange=()=>{let e=state.edges.find(e=>e.id===el.dataset.length),ss=cableSegments(e);ss[Number(el.dataset.piece)].length=Number(el.value);try{applyCableSections(e.id,ss)}catch(err){toast(err.message);cables()}});$('#csv').onclick=()=>download('patchflow-cables.csv','\ufeff'+[['No','From','Output','To','Input','Cable','Length m','Segment','Comment','Route total m'],...pieces.map(({edge:e,segment:s,index,type},i)=>[i+1,node(e.from).name,getport(e.from,e.fp).label,node(e.to).name,getport(e.to,e.tp).label,type,s.length,index?'延長 '+index:'ケーブル 1',s.note||'',e.length])].map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv')}

function download(name,data,type){let u=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function check(){let errs=[],used=new Set;state.edges.forEach(e=>{let a=getport(e.from,e.fp),b=getport(e.to,e.tp);if(!a||!b){errs.push('存在しない端子');return}let err=compatible(a,b)||((isVideo||isUnified)&&videoEdgeError(a,b,e));if(err)errs.push(err);for(let v of [e.from+':'+e.fp,e.to+':'+e.tp]){if(used.has(v))errs.push('端子の二重使用');used.add(v)}});for(let n of state.nodes){let m=models[n.model];if(m.category==='passive'){let feed=state.edges.find(e=>e.to===n.id);if(!feed)errs.push(n.name+': アンプ未接続');else if(models[node(feed.from)?.model]?.category!=='amp')errs.push(n.name+': アンプが必要')}if(m.category==='amp'){for(let c of ['A','B']){let outputs=state.edges.filter(e=>e.from===n.id&&getport(e.from,e.fp)?.channel===c);let inputs=state.edges.filter(e=>e.to===n.id&&getport(e.to,e.tp)?.channel===c);if(outputs.length&&!inputs.length)errs.push(n.name+' CH '+c+': ライン入力未接続');if(outputs.length>1)errs.push(n.name+' CH '+c+': 出力の並列使用は対象外');if(inputs.length>1)errs.push(n.name+' CH '+c+': 入力重複')}}};if(isUnified)errs.push(...avProjectErrors(state));let warnings=isVideo||isUnified?videoGraphWarnings(state):[];if(isUnified&&typeof rentalGraphWarnings==='function')warnings.push(...rentalGraphWarnings(state));if(isUnified&&typeof portableAudioWarnings==='function')warnings.push(...portableAudioWarnings(state));if(isUnified&&typeof audioLevelWarnings==='function')warnings.push(...audioLevelWarnings(state));$('#status').textContent=errs.length?errs.length+' 件の接続エラー':warnings.length?warnings.length+' 件の確認事項':'接続に問題はありません';toast(errs.length?errs.join(' / '):warnings.length?'接続規格OK / 要確認: '+warnings.join(' / '):'✓ '+cableInventory(state.edges).length+'本のケーブルを確認 · '+(isVideo?'端子規格・重複・映像フォーマットを確認しました（内部設定・HDCPは対象外）':'端子規格・重複・アンプ経路に問題はありません（内部設定は対象外）'))}
$('#search').oninput=catalog;$('#categoryfilter').innerHTML='<option value="all">すべての種類</option>'+Object.entries(categoryNames).filter(([k])=>Object.values(models).some(m=>m.category===k&&(!isVideo||m.domain==='video'))).map(([k,v])=>`<option value="${k}">${v}</option>`).join('');$('#brandfilter').innerHTML='<option value="all">すべてのブランド</option>'+[...new Set(Object.values(models).filter(m=>!m.legacy&&(!isVideo||m.domain==='video')).map(m=>m.maker))].map(v=>`<option>${v}</option>`).join('');$('#categoryfilter').onchange=e=>{filter=e.target.value;catalog()};$('#brandfilter').onchange=e=>{brandFilter=e.target.value;catalog()};$('#groupby').onchange=e=>{groupBy=e.target.value;catalog()};$$('[data-filter]').forEach(el=>el.onclick=()=>{filter=el.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===el));catalog()});$$('[data-tab]').forEach(el=>el.onclick=()=>{activeTab=el.dataset.tab;$$('[data-tab]').forEach(x=>x.classList.toggle('active',x===el));$('#canvasframe').style.display=activeTab==='canvas'?'block':'none';$('#cableview').hidden=activeTab!=='cables';$('#canvastools').style.display=activeTab==='canvas'?'flex':'none';if(activeTab==='canvas')requestAnimationFrame(wires)});
let editedTitle=false;$('#title').onfocus=()=>{editedTitle=false};$('#title').oninput=e=>{if(!editedTitle){remember();editedTitle=true}state.title=e.target.value.trim()||'Untitled Session';save();$('#undo').disabled=!history.length};$('#check').onclick=check;$('#undo').onclick=()=>{if(history.length){state=JSON.parse(history.pop());pending=null;rewire=null;insertDraft=null;render()}};$('#reset').onclick=()=>{remember();state=demo();pending=null;rewire=null;insertDraft=null;selected='m1';selectedEdge=null;selectedGroup=null;render();requestAnimationFrame(fitCanvas);toast('デモの構成を復元しました（↶で元に戻せます）')};$('#export').onclick=()=>download('patchflow-project.json',JSON.stringify(state,null,2),'application/json');$('#import').onclick=()=>$('#file').click();
function validate(s){if(s.layers!==undefined&&(!s.layers||typeof s.layers!=='object'||Array.isArray(s.layers)||['audio','video'].some(k=>s.layers[k]!==undefined&&typeof s.layers[k]!=='boolean')))throw Error('表示レイヤーの形式が不正です');let cw=s.canvas?.width||4800,ch=s.canvas?.height||3200;if(![cw,ch].every(Number.isFinite)||cw<1400||cw>20000||ch<1000||ch>20000)throw Error('キャンバスのサイズが不正です');if(s.camera&&(![s.camera.zoom,...(s.camera.version===2?[s.camera.cx,s.camera.cy]:[s.camera.x,s.camera.y])].every(Number.isFinite)||s.camera.zoom<.1||s.camera.zoom>2.5))throw Error('表示位置が不正です');if(s.version!==1||typeof s.title!=='string'||s.title.length>200||!Array.isArray(s.nodes)||!Array.isArray(s.edges)||s.nodes.length>100||s.edges.length>500)throw Error('ファイル形式が異なります');if(isVideo&&!isUnified&&s.nodes.some(n=>models[n.model]?.domain!=='video'))throw Error('音響プロジェクトはAudioページで読み込んでください');if(s.groups!==undefined){if(!Array.isArray(s.groups)||s.groups.length>30)throw Error('ブース形式が不正です');let gids=new Set;for(let g of s.groups){if(typeof g.id!=='string'||!/^[a-zA-Z0-9_-]+$/.test(g.id)||gids.has(g.id)||typeof g.name!=='string'||g.name.length>100||g.subtitle!==undefined&&typeof g.subtitle!=='string'||![g.x,g.y,g.w,g.h].every(Number.isFinite)||g.x<0||g.y<0||g.w<100||g.h<100||g.x+g.w>cw||g.y+g.h>ch)throw Error('ブースデータが不正です');gids.add(g.id)}}let ids=new Set;for(let n of s.nodes){if(typeof n.model!=='string'||!Object.prototype.hasOwnProperty.call(models,n.model)||typeof n.id!=='string'||!/^[a-zA-Z0-9_-]+$/.test(n.id)||ids.has(n.id)||typeof n.name!=='string'||n.name.length>100||n.group!==undefined&&typeof n.group!=='string'||!Number.isFinite(n.x)||!Number.isFinite(n.y)||n.x<0||n.x>cw-100||n.y<0||n.y>ch-100)throw Error('機材データが不正です');ids.add(n.id)}let used=new Set,edgeids=new Set;for(let e of s.edges){let a=s.nodes.find(n=>n.id===e.from),b=s.nodes.find(n=>n.id===e.to);let ap=models[a?.model]?.ports.find(p=>p.id===e.fp),bp=models[b?.model]?.ports.find(p=>p.id===e.tp);if(!ap||!bp||compatible(ap,bp)||((isVideo||isUnified)&&videoEdgeError(ap,bp,e))||(bp.signal==='speaker'&&models[a?.model]?.category!=='amp')||e.type!==cableType(ap,bp)||typeof e.id!=='string'||!/^[a-zA-Z0-9_-]+$/.test(e.id)||edgeids.has(e.id)||!Number.isFinite(e.length)||e.length<=0||e.length>1000)throw Error('接続データが不正です');if(e.segments!==undefined)validateCableSegments(e);edgeids.add(e.id);for(let v of [e.from+':'+e.fp,e.to+':'+e.tp]){if(used.has(v))throw Error('端子の二重使用があります');used.add(v)}}for(let n of s.nodes){let m=models[n.model];if(m.category==='passive'&&s.edges.filter(e=>e.to===n.id).length>1)throw Error('パッシブの並列入力は対象外です');if(m.category==='amp'){for(let c of ['A','B']){if(s.edges.filter(e=>e.from===n.id&&m.ports.find(p=>p.id===e.fp)?.channel===c).length>1||s.edges.filter(e=>e.to===n.id&&m.ports.find(p=>p.id===e.tp)?.channel===c).length>1)throw Error('同じアンプチャンネルの重複使用です')}}}if(isUnified){let errors=avProjectErrors(s);if(errors.length)throw Error(errors[0])}return s}
$('#file').onchange=async e=>{if(!e.target.files?.length)return;try{let raw=JSON.parse(await e.target.files[0].text());if(raw.kind==='patchflow-project-library'){if(raw.version!==1||!Array.isArray(raw.projects)||!raw.projects.length)throw Error('プロジェクト一覧の形式が不正です');let incoming=raw.projects.map(p=>validate(p.data)),deleted=(raw.trash||[]).map(p=>validate(p.data));if(!saveBeforeSwitch())return;projectLibrary.merge(incoming,deleted);loadActiveProject();toast(incoming.length+'件を新しいプロジェクトとして読み込みました')}else{let data=validate(raw);if(!saveBeforeSwitch())return;projectLibrary.create(data);loadActiveProject();toast('別のプロジェクトとして読み込みました')}}catch(err){toast('読み込み失敗: '+err.message)}e.target.value=''};
function setZoom(z,anchor){let view=$('#canvaswrap'),old=zoom,pad=canvasPadding(),visible=visibleViewport(),px=anchor?anchor.x:visible.x+visible.w/2,py=anchor?anchor.y:visible.h/2,wx=(view.scrollLeft+px-pad.x)/old,wy=(view.scrollTop+py-pad.y)/old;zoom=Math.min(2.5,Math.max(.1,z));$('#board').style.scale=zoom;syncCanvasSize();$('#zoomlabel').textContent=Math.round(zoom*100)+'%';$('#zoomrange').value=Math.round(zoom*100);view.scrollLeft=pad.x+wx*zoom-px;view.scrollTop=pad.y+wy*zoom-py;queueCameraSave();requestAnimationFrame(wires)}
function fitCanvas(){let v=$('#canvaswrap');if(!v.clientWidth||!v.clientHeight)return;let b=contentBounds(),pad=canvasPadding(),visible=visibleViewport(),z=Math.max(.1,Math.min(1,(visible.w-100)/b.w,(visible.h-100)/b.h));setZoom(z);v.scrollLeft=pad.x+(b.x+b.w/2)*zoom-visible.x-visible.w/2;v.scrollTop=pad.y+(b.y+b.h/2)*zoom-visible.h/2;queueCameraSave()}

$('#minus').onclick=()=>setZoom(zoom-.1);$('#plus').onclick=()=>setZoom(zoom+.1);$('#zoomlabel').onclick=()=>setZoom(1);$('#zoomrange').oninput=e=>setZoom(Number(e.target.value)/100);$('#fit').onclick=fitCanvas;
$('#canvaswrap').addEventListener('wheel',e=>{if(!e.ctrlKey&&!e.metaKey)return;e.preventDefault();let r=$('#canvaswrap').getBoundingClientRect();setZoom(zoom*Math.exp(-e.deltaY*.006),{x:e.clientX-r.left,y:e.clientY-r.top})},{passive:false});
$('#movegroup').onchange=e=>{selectedGroup=e.target.value||null;selectedEdge=null;pending=null;render();if(selectedGroup)toast('グループ移動中：見出しや所属機材の上部をドラッグ。右の矢印でも移動できます。Escで終了')};
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]'))return;if(e.key==='Escape'){pending=null;selectedEdge=null;selectedGroup=null;rewire=null;insertDraft=null;render()}if((e.key==='Delete'||e.key==='Backspace')&&selectedEdge&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();deleteCable(selectedEdge)}if((e.ctrlKey||e.metaKey)&&e.key==='z'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('#undo').click()}});window.addEventListener('resize',wires);
$('#svgexport').onclick=async()=>{toast('実機写真を含むSVGを準備しています…');const imgs={};try{for(let key of new Set(state.nodes.map(n=>n.model))){let m=models[key];{let b=await(await fetch(m.img)).blob();imgs[key]=await new Promise((res,rej)=>{let r=new FileReader;r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(b)})}}let eb=contentBounds();let out=`<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="${Math.ceil(eb.w+80)}" height="${Math.ceil(eb.h+150)}" viewBox="0 0 ${Math.ceil(eb.w+80)} ${Math.ceil(eb.h+150)}"><rect width="100%" height="100%" fill="#14181a"/><text x="35" y="47" fill="#d0f887" font-size="26" font-family="sans-serif">PATCHFLOW / ${esc(state.title)}</text><g transform="translate(${40-eb.x},${85-eb.y})">${state.groups.map(g=>`<rect x="${g.x}" y="${g.y}" width="${g.w}" height="${g.h}" rx="16" fill="#233020" fill-opacity=".35" stroke="#485741" stroke-dasharray="5 5"/><text x="${g.x+20}" y="${g.y+30}" font-size="15" fill="#b8c9a9" font-family="sans-serif">${esc(g.name)}</text>`).join('')}${$('#wires').innerHTML}`;for(let n of state.nodes){let el=$(`.node[data-id="${n.id}"]`),h=el.offsetHeight,m=models[n.model];out+=`<g transform="translate(${n.x},${n.y})"><rect width="215" height="${h}" rx="9" fill="#22292b" stroke="#63705d"/><text x="12" y="20" fill="#a8b79f" font-size="10" font-family="sans-serif">${esc(m.maker)}</text><text x="12" y="40" fill="white" font-size="12" font-family="sans-serif">${esc(n.name)}</text><image x="20" y="60" width="175" height="120" xlink:href="${imgs[n.model]}"/>`;for(let p of m.ports.filter(p=>expandedNodes.has(n.id)&&p.dir!=='io'||rewire&&p.dir===(rewire.end==='to'?'in':'out')&&(p.signal==='line'||p.accept?.includes('line'))||m.visible.includes(p.id)||occupied(n.id,p.id))){let pt=point(n.id,p.id);if(pt)out+=`<text x="${p.dir==='out'?202:12}" y="${pt.y-n.y+3}" text-anchor="${p.dir==='out'?'end':'start'}" font-size="9" fill="${colors[p.type]||colors.XLR}" font-family="sans-serif">${esc(p.label)}</text>`}out+='</g>'}out+=`</g><text x="35" y="${Math.ceil(eb.h+125)}" font-size="12" fill="#91a18a" font-family="sans-serif">${state.nodes.length} devices · ${state.edges.length} cables | 音声配線図 / 電源・内部ルーティングは対象外</text></svg>`;download('patchflow-diagram.svg',out,'image/svg+xml');toast('SVGを書き出しました')}catch(e){toast('画像の取得に失敗しました。JSON保存をお試しください')}};
