 if(isUnified)bindGroupResizing();$$('[data-group]').forEach(el=>{el.querySelector('.zonehandle').onpointerdown=e=>startGroupDrag(e,el.dataset.group,el.querySelector('.zonehandle'));el.querySelector('.zonehandle').onclick=()=>{selectedGroup=el.dataset.group;selectedEdge=null;render()};el.onpointerdown=e=>{if(e.target===el&&selectedGroup===el.dataset.group)startGroupDrag(e,el.dataset.group,el)}})
