function openReplacement(id){let n=node(id);if(!n)return;let options=replacementOptions(n.model);let ranked=options.map(([k,m])=>({key:k,model:m,plan:planReplacement(state,id,k)})).sort((a,b)=>(models[n.model].category===b.model.category)-(models[n.model].category===a.model.category));let first=ranked.find(p=>p.plan.complete)||ranked[0];replacementSession={id,target:first?.key||'',mapping:first?{...first.plan.mapping}:{},name:null};pending=null;rewire=null;insertDraft=null;renderReplacement();let d=$('#replacementdialog');d.onclose=()=>{replacementSession=null};if(!d.open)d.showModal()}
function renderReplacement(){let session=replacementSession,n=session&&node(session.id);if(!n)return;let old=models[n.model],options=replacementOptions(n.model),target=models[session.target],d=$('#replacementdialog');if(!target){d.innerHTML=`<div class="guideheader"><div><small>REPLACE EQUIPMENT</small><h2>機材を交換</h2></div><button id="closereplacement" aria-label="機材交換を閉じる">✕</button></div><div class="replacementbody"><p>現在のライブラリには、同じ種類の交換先がありません。</p><button id="cancelreplacement">閉じる</button></div>`;$('#closereplacement').onclick=$('#cancelreplacement').onclick=()=>d.close();return}let plan=planReplacement(state,n.id,session.target,session.mapping),label=session.name??n.name.replace(old.name,target.name),assigned=plan.rows.filter(r=>plan.mapping[r.key]&&r.candidates.some(p=>p.id===plan.mapping[r.key])).length,ins=plan.rows.filter(r=>r.end==='to').length,outs=plan.rows.filter(r=>r.end==='from').length;let diagnostics=options.map(([k,m])=>{let p=planReplacement(state,n.id,k);return[k,p.complete?'交換可':p.errors.length+'件の確認が必要']});d.innerHTML=`<div class="guideheader"><div><small>REPLACE EQUIPMENT · KEEP YOUR PATCH</small><h2>配線を保って機材を交換</h2></div><button id="closereplacement" aria-label="機材交換を閉じる">✕</button></div><div class="replacementbody"><div class="replacementmodels"><div><img src="${old.img}" alt="${old.name}"><small>現在の機材 / ${old.maker}</small><h3>${old.name}</h3><p>${esc(n.name)}</p></div><span class="replacementarrow">⇄</span><div><img src="${target.img}" alt="${target.name}"><small>交換後 / ${target.maker}</small><select id="replacementmodel" aria-label="交換先の機材">${options.map(([k,m])=>`<option value="${k}" ${k===session.target?'selected':''}>${m.maker} ${m.name} — ${diagnostics.find(([key])=>key===k)[1]}</option>`).join('')}</select><p>${target.ports.filter(p=>p.dir==='in').length} 入力端子 / ${target.ports.filter(p=>p.dir==='out').length} 出力端子</p></div></div><div class="replacementsummary ${plan.complete?'valid':'invalid'}"><div><strong>${plan.complete?'✓ 交換できます':'端子の割り当てを確認してください'}</strong><small>使用中：${ins} 入力 / ${outs} 出力 · 割り当て ${assigned} / ${plan.rows.length}</small></div><button id="replacementauto">自動で割り当て直す</button></div>${plan.errors.length?`<div class="replacementerrors">${plan.errors.map(t=>`<div>・${esc(t)}</div>`).join('')}</div>`:''}<div class="replacementmapping"><table><thead><tr><th>現在の端子 / 接続相手</th><th>交換後の端子</th><th>ケーブル</th></tr></thead><tbody>${plan.rows.map(r=>{let assigned=target.ports.find(p=>p.id===plan.mapping[r.key]),e=r.edges[0],other=node(e[r.end==='from'?'to':'from']),otherPort=getport(other.id,e[r.end==='from'?'tp':'fp']),newType=assigned?cableType(r.end==='from'?assigned:otherPort,r.end==='from'?otherPort:assigned):null;return `<tr class="${!assigned?'unassigned':''}"><td><b>${r.end==='from'?'↗ 出力':'↘ 入力'} ${r.oldPort.label}</b><small>${esc(other.name)} / ${otherPort.label}</small></td><td><select data-replacement-port="${r.key}" aria-label="${r.oldPort.label} の交換先端子"><option value="">未割り当て</option>${r.candidates.map(p=>`<option value="${p.id}" ${p.id===plan.mapping[r.key]?'selected':''}>${p.label} · ${p.type}${plan.rows.some(other=>other.key!==r.key&&plan.mapping[other.key]===p.id)?'（他で使用予定）':''}</option>`).join('')}</select></td><td>${newType===e.type?`<span class="cablekept">維持 · ${cableLabel(e.type)}</span>`:newType?`<span class="cablechanged">${cableLabel(e.type)}<br>→ ${cableLabel(newType)}<br><b>ケーブル交換</b></span>`:'—'}</td></tr>`}).join('')||'<tr><td colspan="3">接続中のケーブルはありません。そのまま交換できます。</td></tr>'}</tbody></table></div>${plan.changes.length?'<div class="replacementwarning">端子形状が変わる接続は、対応表に表示したケーブルへ交換してください。アプリ上のケーブルリストも更新します。</div>':''}<label class="replacementname">交換後の表示名<input id="replacementname" aria-label="交換後の機材名" maxlength="100" value="${esc(label)}"></label><p class="source">位置・所属ブース・ケーブルの接続相手と長さを維持します。入力切替、PAN、バス・出力割り当てなどの内部設定は交換後の実機で確認してください。</p></div><div class="replacementfooter"><span>確定するまで現在の機材・配線は変わりません。</span><button id="cancelreplacement">中止</button><button id="applyreplacement" class="accent" ${plan.complete?'':'disabled'}>この機材へ交換</button></div>`;
 $('#closereplacement').onclick=$('#cancelreplacement').onclick=()=>d.close();$('#replacementmodel').onchange=e=>{session.target=e.target.value;session.mapping=planReplacement(state,n.id,session.target).mapping;session.name=null;renderReplacement()};$('#replacementauto').onclick=()=>{session.mapping=planReplacement(state,n.id,session.target).mapping;renderReplacement()};$$('[data-replacement-port]').forEach(el=>el.onchange=()=>{session.mapping[el.dataset.replacementPort]=el.value;renderReplacement()});$('#replacementname').oninput=e=>{session.name=e.target.value};$('#applyreplacement').onclick=()=>applyReplacement()
}
function applyReplacement(){let session=replacementSession,n=session&&node(session.id);if(!n)return;let old=models[n.model],target=models[session.target],plan=planReplacement(state,n.id,session.target,session.mapping);if(!plan.complete){renderReplacement();toast('交換できません。端子の割り当てを確認してください');return false}let label=(session.name??n.name.replace(old.name,target.name)).trim()||target.name;plan.project.nodes.find(p=>p.id===n.id).name=label;remember();state=plan.project;selected=n.id;selectedEdge=null;selectedGroup=null;pending=null;rewire=null;insertDraft=null;expandedNodes.delete(n.id);$('#replacementdialog').close();render();toast(old.name+' → '+target.name+' に交換しました。↶で元に戻せます');return true}
